import pytest

from kauma.second_exam.aes_bfk import (
    aes128_dec,
    decrypt_sector,
    derive_keys,
    encrypt_sector,
    generate_block_polynomials,
    generate_tweak,
    polynomial_to_bytes,
    xorblk,
)

KEY = bytes.fromhex("5442d887b5345eaead347ab5d1e73624")
S = bytes.fromhex("ff7a8c43735a5c39d1ec0af644695fbf")
T = bytes.fromhex("cf4fccfdd115dad3ba3701a2c81d3dec")
U = bytes.fromhex("1eb2168239992d5ad0d6616cc1996bcb")

SECTOR = 12345678
PLAINTEXT = bytes.fromhex(
    ""
)
CIPHERTEXT_WITH_TAG = bytes.fromhex(
    ""
)


def test_derive_keys():
    assert derive_keys(KEY) == (S, T, U)


def test_generate_tweak():
    assert generate_tweak(12345678) == bytes.fromhex("4e61bc00000000000000000000000000")


@pytest.fixture(scope="module")
def block_polynomials():
    return generate_block_polynomials()


def test_r1_polynomial(block_polynomials):
    assert polynomial_to_bytes(block_polynomials[0][0]) == bytes.fromhex(
        "02000000000000000000000000000000"
    )


def test_q1_polynomial(block_polynomials):
    assert polynomial_to_bytes(block_polynomials[0][1]) == bytes.fromhex(
        "00000000000000000000000000000080"
    )


def test_r32_polynomial(block_polynomials):
    assert polynomial_to_bytes(block_polynomials[31][0]) == bytes.fromhex(
        "00000000010000000000000000000000"
    )


def test_encrypted_tweak_matches_reference():
    encrypted_tweak = aes128_dec(S, generate_tweak(SECTOR))
    assert encrypted_tweak == bytes.fromhex("71bd25a5d51d0125d1cf9ec3231f2421")


def test_encrypted_tweak_xor_r1(block_polynomials):
    encrypted_tweak = aes128_dec(S, generate_tweak(SECTOR))
    result = xorblk(encrypted_tweak, polynomial_to_bytes(block_polynomials[0][0]))
    assert result == bytes.fromhex("73bd25a5d51d0125d1cf9ec3231f2421")


def test_encrypt_sector_matches_reference_without_tag():
    expected_prefix = bytes.fromhex(
        ""
    )
    assert encrypt_sector(SECTOR, KEY, PLAINTEXT).startswith(expected_prefix)


def test_encrypt_sector_with_auth_tag():
    assert encrypt_sector(SECTOR, KEY, PLAINTEXT) == CIPHERTEXT_WITH_TAG


def test_decrypt_sector_roundtrip():
    assert decrypt_sector(SECTOR, KEY, CIPHERTEXT_WITH_TAG) == PLAINTEXT


def test_encrypt_second_sector_matches_without_tag():
    expected_prefix = bytes.fromhex(
        ""
    )
    assert encrypt_sector(999888777666, KEY, PLAINTEXT).startswith(expected_prefix)


def test_decrypt_message_is_valid_utf8():
    message = bytes.fromhex(
        ""
    )
    plaintext = decrypt_sector(2024, KEY, message)
    assert isinstance(plaintext.decode(), str)
